    $heroLines = ['PROJECT', 'ARCHIVE', "A COLLECTION OF THINGS I'VE BUILT."];
    $countPad = str_pad((string) count($projects), 2, '0', STR_PAD_LEFT);

    $renderChars = static function (string $text, string $className): string {
        $out = '';
        foreach (mb_str_split($text, 1, 'UTF-8') as $ch) {
            $rendered = $ch === ' ' ? "\u{00a0}" : e($ch);
            $out .= '<span class="'.e($className).'">'.$rendered.'</span>';
        }
        return $out;
    };
